function url_for(string $path=''): string { return Routing::url($path); }
function esc(mixed $value): string { return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8'); }
function redirect_to(string $path=''): never { header('Location: '.url_for($path)); exit; }
function flash(string $message,string $type='success'): void { $_SESSION['flash']=compact('message','type'); }
function initials(string $name): string { return implode('',array_map(fn($p)=>strtoupper(substr($p,0,1)),array_slice(explode(' ',$name),0,2))); }
function icon(string $name): string {
 $map=['grid'=>'<path d="M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z"/>','calendar'=>'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>','coverage'=>'<circle cx="9" cy="8" r="4"/><path d="M2.5 20c.7-4 2.9-6 6.5-6s5.8 2 6.5 6M17 8v6M14 11h6"/>','team'=>'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>','org'=>'<path d="M3 21h18M5 21V9l7-5 7 5v12M9 21v-6h6v6"/>','search'=>'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>','plus'=>'<path d="M12 5v14M5 12h14"/>','arrow'=>'<path d="m9 18 6-6-6-6"/>','spark'=>'<path d="m12 3 1.4 4.1L17.5 8.5l-4.1 1.4L12 14l-1.4-4.1-4.1-1.4 4.1-1.4z"/>','building'=>'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h2M14 7h2M8 11h2M14 11h2M8 15h2M14 15h2"/>','layers'=>'<path d="m12 2 9 5-9 5-9-5zM3 12l9 5 9-5M3 17l9 5 9-5"/>','briefcase'=>'<rect x="3" y="7" width="18" height="13" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>'];
 return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'.($map[$name]??$map['grid']).'</svg>';
