  <article class="panel span-2"><div class="panel-header"><div><h2>Self-scheduling requests</h2><p>Eligibility is recorded when the employee requests the shift.</p></div></div><?php foreach($requests as $r):?><div class="planning-row"><span><strong><?=esc($r['staff_name'])?></strong><small><?=esc($r['shift_date'].' · '.$r['department_name'].' · '.date('g:i A',strtotime($r['starts_at'])))?></small></span><b class="state-pill <?=$r['status']==='pending'?'gap':'covered'?>"><?=esc(ucfirst($r['eligibility_result']))?> · <?=esc(ucfirst($r['status']))?></b><?php if($r['status']==='pending'):?><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="review_request"><input type="hidden" name="request_id" value="<?=$r['id']?>"><button class="button primary" name="decision" value="approved">Approve</button><button class="button secondary" name="decision" value="denied">Deny</button></form><?php endif;?></div><?php endforeach;?><?php if(!$requests):?><div class="inline-empty"><strong>No requests awaiting review</strong><p>Requests appear here when staff select an open shift.</p></div><?php endif;?></article>
